/* Primeiro nó depois do webhook: confere o segredo compartilhado e segue com
   o corpo do pedido. O token vai no header e nunca na URL — URL aparece em
   log de proxy. Sem `NUTRIELIVE_TOKEN` configurado no n8n, o fluxo PARA:
   aceitar qualquer chamada deixaria qualquer um gravar plano alheio. */
const esperado = $env.NUTRIELIVE_TOKEN;
if (!esperado) throw new Error('NUTRIELIVE_TOKEN não está configurado neste n8n.');

const recebido = $input.first().json.headers?.['x-nutrielive-token'];
if (!recebido || recebido !== esperado) throw new Error('Token do webhook inválido.');

return [{ json: $input.first().json.body }];

/* Modelo às vezes embrulha o JSON em cerca de código, mesmo mandado não
   fazer. Em vez de falhar o fluxo por causa de três acentos graves,
   descasca e tenta de novo. */
const t = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
const limpo = t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
try { return [{ json: JSON.parse(limpo) }]; }
catch (e) { throw new Error('O modelo não devolveu JSON válido: ' + e.message); }

/* =========================================================================
   Monta a SaidaReceitas a partir do que o modelo escolheu.

   O modelo devolve só escolha e quantidade:
     { receitas: [ { title, timeMin, steps: [..],
                     itens: [ { alimentoId, gramas } ] } ],
       usados: [..], ignorados: [ { termo, motivo } ] }

   kcal e macros saem daqui, da tabela do payload. E `kcal` é SEMPRE derivada
   dos macros (4P + 4C + 9G): o servidor confere essa igualdade com tolerância
   de 2 kcal (`validarReceitas`) e descarta TODAS as receitas se uma só não
   fechar.

   `ingredients` é texto, e é o texto que o servidor varre contra as
   restrições. Por isso ele é montado a partir do nome do alimento permitido,
   nunca do texto livre do modelo: uma palavra inventada ali derruba o lote
   inteiro por "restricao_violada".
   ========================================================================= */
const entrada = $('Conferir token').first().json;
const bruto = $input.first().json;

const porId = new Map(entrada.alimentosPermitidos.map((a) => [a.id, a]));
/* ---------------------- higiene de texto livre --------------------------
   O servidor varre título, nome de item e passo de preparo contra os termos
   das restrições, e descarta o PLANO INTEIRO se achar um. O modelo erra
   justamente aqui: escolhe o alimento certo e escreve "Iogurte com fruta"
   no título de um plano sem lactose. Então o texto é limpo antes de sair.
   `termosProibidos` é a mesma lista que a validação usa (`termosBloqueados`
   em seguranca.ts), então não há como as duas discordarem. */
const proibidos = (entrada.restricoes.termosProibidos || []).filter(Boolean);
const semAcento = (t) => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const violaTexto = (t) => {
  const n = semAcento(t);
  return proibidos.some((p) => new RegExp('(^|[^a-z0-9])' + p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(n));
};
const textoSeguro = (t, reserva) => (t && !violaTexto(t) ? String(t) : reserva);

const r1 = (n) => Math.round(n * 10) / 10;
const energia = (m) => Math.round(m.protein * 4 + m.carb * 4 + m.fat * 9);

const cruas = Array.isArray(bruto?.receitas) ? bruto.receitas : [];
if (!cruas.length) throw new Error('O modelo não devolveu nenhuma receita.');

/* O que a pessoa digitou, para medir o aproveitamento de cada receita. */
const pedidos = String(entrada.pedido.ingredientes || '')
  .split(/[,;\n]+/).map((s) => s.trim().toLowerCase()).filter(Boolean);

const receitas = cruas.map((rc) => {
  const itens = (Array.isArray(rc.itens) ? rc.itens : [])
    .map((it) => {
      const a = porId.get(it?.alimentoId);
      if (!a) return null;                          /* inventado: fora */
      const gramas = Math.max(a.min, Math.min(a.max, Math.round(Number(it.gramas) || 0)));
      return gramas > 0 ? { a, gramas } : null;
    })
    .filter(Boolean);

  if (!itens.length) return null;

  const macros = itens.reduce((t, { a, gramas }) => {
    const f = gramas / 100;
    return {
      protein: r1(t.protein + a.proteina100 * f),
      carb: r1(t.carb + a.carbo100 * f),
      fat: r1(t.fat + a.gordura100 * f)
    };
  }, { protein: 0, carb: 0, fat: 0 });

  /* Aproveitamento: quantos dos ingredientes pedidos a receita usa de fato.
     Sem ingrediente pedido (pessoa só quer ideia), vale 100. */
  const nomes = itens.map(({ a }) => a.nome.toLowerCase() + ' ' + a.nomeDeCompra.toLowerCase());
  const usados = pedidos.filter((p) => nomes.some((n) => n.includes(p)));
  const matchPct = pedidos.length ? Math.round((usados.length / pedidos.length) * 100) : 100;

  return {
    title: textoSeguro(String(rc.title || '').slice(0, 120), 'Receita de ' + itens[0].a.nome.toLowerCase()),
    timeMin: Math.max(5, Math.min(180, Math.round(Number(rc.timeMin) || 25))),
    kcal: energia(macros),
    macros,
    ingredients: itens.map(({ a, gramas }) => `${a.nome} — ${gramas} g`),
    steps: (Array.isArray(rc.steps) ? rc.steps : [])
      .map((s) => String(s).slice(0, 300))
      .filter((s) => !violaTexto(s))
      .slice(0, 10),
    matchPct
  };
}).filter(Boolean);

if (!receitas.length) throw new Error('Nenhuma receita sobrou depois de descartar alimentos fora da lista permitida.');

/* O que a pessoa pediu e a base não tem: dizer isso é melhor que entregar
   receita sem explicar por que o ingrediente dela não apareceu. */
const todosOsNomes = receitas.flatMap((r) => r.ingredients.map((i) => i.toLowerCase()));
const ignorados = pedidos
  .filter((p) => !todosOsNomes.some((n) => n.includes(p)))
  .map((termo) => ({ termo, motivo: 'não está na nossa base de alimentos ou foi bloqueado pelas suas restrições' }));

return [{
  json: {
    jobId: entrada.jobId,
    status: 'concluido',
    output: {
      tipo: 'receitas',
      versao: 1,
      receitas: receitas.sort((a, b) => b.matchPct - a.matchPct),
      usados: pedidos.filter((p) => todosOsNomes.some((n) => n.includes(p))),
      ignorados,
      avisos: [],
      gerado: { driver: 'n8n', em: new Date().toISOString(), semente: entrada.semente }
    },
    executionId: $execution.id,
    tokensIn: $('Modelo').first().json?.tokenUsage?.promptTokens ?? null,
    tokensOut: $('Modelo').first().json?.tokenUsage?.completionTokens ?? null
  }
}];

/* Caminho de erro: o app precisa saber que o job morreu, senão ele fica
   "processando" para sempre e a pessoa olha uma tela girando. A mensagem vai
   em português porque é ela que aparece na tela — e em /admin/ia. */
const erro = $input.first().json;
let jobId = null;
try { jobId = $('Conferir token').first().json.jobId; } catch (e) {}
if (!jobId) { try { jobId = $('Webhook').first().json.body?.jobId; } catch (e) {} }

return [{
  json: {
    jobId,
    status: 'erro',
    error: 'A geração por IA não terminou: ' + String(erro?.message || erro?.error || 'falha no fluxo do n8n'),
    executionId: $execution.id
  }
}];
